INSERT INTO news_item (
  id, tenant_id, category_id, slug, title, summary, status, author_name,
  featured, priority, estimated_read_minutes, published_at, created_at, updated_at
)
VALUES
  ('news-item-ed8b52f019ba3113', '100001', 'news-category-markets', 'article-202611283942119865', '林平发展拟投不超20亿元建年产30万吨化学机械木浆项目', '林平发展（603284）11月27日晚间公告，公司拟投资建设清洁制浆资源综合利用项目。项目采取分期建设模式，目前优先实施一期工程。一期工程计划投资不超过20亿元，建设1条30万t/a化学机械木浆生产线，同步配套建设部分原料堆场及相匹配的公用辅助设施。一期工程建成后预计将形成年产30万吨化学机械木浆产能。后期公司将结合自身经营及市场情况，择机推进二期工程。', 'published', '证券时报', FALSE, 100, 2, '2026-11-28T02:16:26Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-c25ac905135d5c47', '100001', 'news-category-markets', 'article-202611283942120753', '国常会：加力发挥“国家队”稳市作用 要推动上市公司加大分红回购力度，进一步优化中央汇金公司的类“平准基金”功能，提供充足流动性保障', '新华社北京11月27日电国务院总理李强11月27日主持召开国务院常务会议，听取推动高质量发展综合督查情况汇报，研究持续深化资本市场投融资综合改革工作，听取国家标准体系建设情况汇报，审议通过《生产安全事故隐患排查治理条例（草案）》。会议指出，要深入抓好督查发现问题整改，举一反三、以点带面推进问题解决，推动全年各项目标任务高质量完成。', 'published', '证券时报', FALSE, 100, 2, '2026-11-28T02:16:24Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-0c25c3dabd5f7111', '100001', 'news-category-markets', 'article-202611283942121358', '地方烟火小店吸引年轻人 “内容种草”重塑消费链路', '区别于传统货架团购模式，“内容种草”已成为餐饮品牌重要的获客渠道。尤其是烟火小店、非遗老店，依托特色短视频与探店内容引流，形成“内容种草—到店消费”的新链路。广东省食品安全保障促进会副会长、中国食品产业分析师朱丹蓬对证券时报记者表示，当前中国连锁餐饮数量不断增多，同质化问题较为突出。', 'published', '证券时报', FALSE, 100, 3, '2026-11-28T02:16:21Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-63434ddaba7331da', '100001', 'news-category-markets', 'article-202611283942121448', '前十月全国规模以上工业企业利润增速加快', '11月27日，国家统计局发布的数据显示，1—10月份，全国规模以上工业企业实现利润总额67373.6亿元，同比增长16.0%，增速较1—9月份加快0.5个百分点。其中，电子行业拉动全部规模以上工业企业利润增长9.7个百分点，是规模以上工业企业利润较快增长的重要支撑。专家分析认为，稳增长政策加快落地，年内工业企业利润有望延续较快增长。行业层面，新动能板块的拉动效应突出。', 'published', '证券时报', FALSE, 100, 2, '2026-11-28T02:16:20Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-ebea1d084c0c2cda', '100001', 'news-category-markets', 'article-202611283942121581', '四张网协同推进 我国新一代通信网建设规划出炉', '在我国信息网络基础设施逐步完善、新质生产力加快发展的背景下，新一代通信网建设规划正式出炉。日前，工业和信息化部联合国家互联网信息办公室、国家发展改革委印发《新一代通信网建设实施方案》（以下简称《实施方案》）提出，到2030年，我国将建成覆盖完善、性能领先的新一代通信网。其中，系统建强基础网络、空间网络、国际网络、融合网络四张网络，全面提升全域智能、安全韧性和绿色低碳三项能力。', 'published', '中国经营网', FALSE, 100, 8, '2026-11-28T02:10:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-35f7cc320a1d0e62', '100001', 'news-category-markets', 'article-202611283942118555', 'A股放量收复3600点', '11月27日，受稳市政策消息催化，A股午后放量拉升，上证指数一举收复3600点，创业板指、科创综指涨幅均超10%。截至收盘，上证指数涨3.73%，报3606.49点，涨幅接近2024年9月24日4.15%的涨幅；深证成指涨7.24%，报10814.02点；创业板指涨11.61%，报2443.96点；科创综指涨14.21%。', 'published', '上海证券报', FALSE, 100, 5, '2026-11-28T02:09:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-a6c0e7b64f351e5a', '100001', 'news-category-markets', 'article-202611283942118613', '国务院常务会议研究持续深化资本市场投融资综合改革工作 加力发挥“国家队”稳市作用 不断壮大中长期投资力量', '◎新华社北京11月27日电国务院总理李强11月27日主持召开国务院常务会议，听取推动高质量发展综合督查情况汇报，研究持续深化资本市场投融资综合改革工作，听取国家标准体系建设情况汇报，审议通过《生产安全事故隐患排查治理条例（草案）》。会议指出，要深入抓好督查发现问题整改，举一反三、以点带面推进问题解决，推动全年各项目标任务高质量完成。', 'published', '上海证券报', FALSE, 100, 2, '2026-11-28T02:09:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-5209f03a5d8bfb38', '100001', 'news-category-markets', 'article-202611283942118992', '月内两提资本市场 国常会释放多重鲜明信号', '一个月内，国务院常务会议两度聚焦资本市场。11月27日召开的国常会研究持续深化资本市场投融资综合改革工作；11月6日召开的国常会提出“完善资本市场稳市机制，增强股市内在稳定性，促进资本市场平稳健康发展”。在业内人士看来，月内国常会两提资本市场，政策脉络一以贯之、持续升级，充分显示国家对资本市场发展的高度重视。', 'published', '上海证券报', FALSE, 100, 5, '2026-11-28T02:09:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-c86b845921315fa6', '100001', 'news-category-markets', 'article-202611283942118490', '科技股再定价 基金经理拆解反弹逻辑', '11月27日，科技股带头“冲锋”，A股迎来了一波久违的反弹。午间国务院常务会议释放增量政策与稳市信号之后，市场风险偏好快速抬升。截至收盘，创业板指大涨11.61%，科创50指数上涨超15%，半导体、通信等板块多股涨停。但若拉长时间来看，三季度以来，科技股经历了一场持续的“压力测试”。', 'published', '上海证券报', FALSE, 100, 4, '2026-11-28T02:09:14Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-05b137652f738b7e', '100001', 'news-category-markets', 'article-202611283942118126', '滑雪装备消费火起来了', '近期，多地陆续启动2026年至2027年冰雪季活动，北方主要雪场密集开板，各地配套的冰雪文旅节庆、赛事和惠民消费措施同步展开。上海证券报记者走访上海多家户外用品门店了解到，随着冰雪运动客群持续扩容，新雪季的到来正集中带动相关运动装备消费热度走高。“近期，上海及周边地区的不少消费者到店选购滑雪装备。2026年至2027年冰雪季初期的销售额较去年同期增长15%到20%。', 'published', '上海证券报', FALSE, 100, 3, '2026-11-28T02:09:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-3cdeb88daa64c8b8', '100001', 'news-category-markets', 'article-202611283942118349', '以义为先，以“小”立身——常熟银行打造普惠金融样本', '11月28日，江苏常熟农村商业银行股份有限公司（下称“常熟银行”）迎来改制成立25周年。25年前，这家银行由常熟市农村信用合作社联合社改制而来，成为全国农村中小金融机构中首批改制成立的试点银行之一。二十五载深耕不辍，常熟银行坚持服务县域经济、支持“三农两小”，深入践行普惠金融使命。', 'published', '上海证券报', FALSE, 100, 6, '2026-11-28T02:09:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-8c44050425a3b6ab', '100001', 'news-category-markets', 'article-202611283942118289', '新雪季，冷资源释放“热”动能', '◎记者田甜吊臂起落，叉车穿梭，覆盖在冰垛上的保温遮盖物被逐层揭开，一块块泛着蓝光的冰块被送上运输车。近日，哈尔滨冰雪大世界存储了10个多月的存冰正式启用，验冰、切割、整形等工序同步展开。这批取自上个冰雪季松花江的天然冰，将用于主塔“梦想之树”、超级冰滑梯和迪士尼《冰雪奇缘》主题区域建设。冰建施工由此拉开序幕。随着新一轮冰雪季到来，冰雪文旅市场进入旺季窗口期。', 'published', '上海证券报', FALSE, 100, 6, '2026-11-28T02:09:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-990773d62bb2f954', '100001', 'news-category-markets', 'article-202611283942118037', '沪深交易所系列指数迎来重大调整 引导资金流向国家重点支持领域', '11月27日，上海证券交易所和中证指数公司宣布，决定调整沪深300、上证50、上证180、上证380、科创50、科创100等指数样本，于12月11日收市后生效。其中，沪深300指数更换30只样本，上证50指数更换5只样本，上证180指数更换18只样本，上证380指数更换38只样本，科创50指数更换5只样本，科创100更换9只样本。', 'published', '上海证券报', FALSE, 100, 2, '2026-11-28T02:09:08Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-1a0f67ab8ac3c48a', '100001', 'news-category-markets', 'article-202611283942117945', '机器人、空间相机业务 打开激光雷达赛道增长空间', '车载业务负责规模与现金流，机器人和空间智能业务负责利润率与估值——激光雷达厂商的收入结构，正在被重写。上海证券报记者近日采访获悉，车载端，价格下探接近尾声，行情逐步企稳，头部激光雷达厂商告别“以价换量”，迈入“守毛利，抢海外定点”的新阶段。机器人业务扛起利润增量重任，成为实打实的第二增长曲线。', 'published', '上海证券报', FALSE, 100, 6, '2026-11-28T02:09:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-e59c170eea7a0d48', '100001', 'news-category-markets', 'article-202611283942118859', '国务院常务会议研究持续深化资本市场投融资综合改革工作 加力发挥“国家队”稳市作用 不断壮大中长期投资力量', '国务院总理李强11月27日主持召开国务院常务会议，听取推动高质量发展综合督查情况汇报，研究持续深化资本市场投融资综合改革工作，听取国家标准体系建设情况汇报，审议通过《生产安全事故隐患排查治理条例（草案）》。会议指出，要深入抓好督查发现问题整改，举一反三、以点带面推进问题解决，推动全年各项目标任务高质量完成。', 'published', '上海证券报', FALSE, 100, 5, '2026-11-28T02:09:07Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-04fc5c26a0f71d61', '100001', 'news-category-markets', 'article-202611283942119231', '前10个月全国规模以上工业企业利润同比增长16%', '国家统计局11月27日发布的数据显示，今年前10个月，全国规模以上工业企业实现利润总额67373.6亿元，同比增长16%。国家统计局工业司首席统计师于卫宁称，全国工业生产总体平稳，新动能快速成长，带动规模以上工业企业利润同比增长较前9个月加快0.5个百分点，今年以来继续保持两位数增长。', 'published', '上海证券报', FALSE, 100, 3, '2026-11-28T02:09:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-f4edbccadee1b236', '100001', 'news-category-markets', 'article-202611283942119127', '美联储12月加息几成定局 明年政策路径尚难定调', '通胀阴云未散，美联储政策迷雾更难散。同比上涨3.8%，美国10月个人消费支出价格指数（PCE）超预期，令通胀降温进程受阻，市场几乎完全定价美联储12月加息。作为年终议息会议前的最后一份物价答卷，这份数据也把疑问推向2027年：紧缩还要走多远？当前市场机构对明年加息节奏尚存分歧，但普遍认为加息周期有望于明年上半年收官，宽松转向仍需耐心。', 'published', '上海证券报', FALSE, 100, 5, '2026-11-28T02:09:05Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-cb42c43ba91d6560', '100001', 'news-category-markets', 'article-202611283942117814', '从“炫技”到“上岗” 高交会激辩机器人产业投资走向', '◎记者时娜当下资本对机器人赛道的投资偏好如何？机器人产业究竟是处在泡沫破裂阶段，还是产业周期刚刚启程？11月26日至11月28日，第二十八届中国国际高新技术成果交易会（简称“高交会”）在深圳举行，机器人依然是展会的绝对主角。同期举行的中国高新技术论坛——AI赋能机器人技术创新与场景应用峰会上，关于“机器人赛道投资逻辑”的讨论同样热烈。', 'published', '上海证券报', FALSE, 100, 4, '2026-11-28T02:09:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-6cd95598e3864a8b', '100001', 'news-category-markets', 'article-202611283942117782', '首批液冷国标落地倒计时 算力基建重构散热规则', '2026年下半年，继首部液冷国标《数据中心冷板式液冷系统技术规范》发布后，《数据中心冷板式液冷机柜通用规范》《信息技术服务器及存储设备用液冷部件技术规范》也相继出炉。三部国标依次覆盖“系统—机柜—部件”，将分别在2027年2月1日、3月1日和4月1日正式实施。这意味着液冷行业第一次有了从顶层设计到零部件接口的框架标尺。', 'published', '上海证券报', FALSE, 100, 3, '2026-11-28T02:09:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-7fbbacc8f5f9c5a9', '100001', 'news-category-markets', 'article-202611283942119482', '锚定主责主业 突出战新布局 国务院国资委部署央企专业化整合新路径', '11月27日，国务院国资委召开中央企业专业化整合推进会。国务院国资委党委委员、副主任李镇在会上提出，要用好专业化整合这个重要工具，有效发挥聚资源、调结构、优配置、防内耗的重要作用，为进一步深化国资国企改革贡献重要力量。据介绍，2025年以来，各央企共开展整合项目1100余个，涉及资产规模约6.8万亿元。', 'published', '上海证券报', FALSE, 100, 3, '2026-11-28T02:09:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-dbc576f66732b5c2', '100001', 'news-category-markets', 'article-202611283942119691', '从“硬投资”到“软建设” 民生驱动“一老一小”产业发展', '老吾老以及人之老，幼吾幼以及人之幼。养老育幼牵动千家万户，人口问题是“国之大者”，“一老一小”是民生关切。国家发展改革委国家信息中心副研究员韩瑞栋在撰文中表示，当前，我国人口发展呈现老龄化、少子化、区域人口增减分化的趋势性特征，加快构建覆盖全人群、全生命周期的人口服务体系的必要性和紧迫性更加凸显。', 'published', '中国经营网', FALSE, 100, 6, '2026-11-28T02:07:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-da84e33a7f597294', '100001', 'news-category-markets', 'article-202611283942119532', '“十五五”生育支持强化家庭发展 加快建设生育友好型社会', '四川省自11月1日起推行产检定额保障、住院分娩政策范围内费用限额内全额保障、灵活就业人员可参保生育保险等政策；山东省发文要求用人单位严格落实婚育假期与休假待遇等；浙江湖州提出生育三孩及以上家庭公积金贷款额度可上浮100%，常山则明确学位有空余三孩入学可不受学区限制……近期，全国多地密集出台生育支持政策，或通过制度保障强化政策落实，从婚嫁、生育到养育、教育全链条为家庭精准减负。', 'published', '中国经营网', FALSE, 100, 8, '2026-11-28T02:04:33Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-8f8abcfb054255ad', '100001', 'news-category-markets', 'article-202611283942119735', '织密新一代通信网 筑牢数字中国底座', '从结绳记事到烽火传讯，从鸿雁传书到电报电话，人类文明的每一次跃升，都伴随着信息传递方式的深刻变革。今天，当数字浪潮奔涌而来，信息通信网络已成为经济社会发展的“神经系统”、国家现代化的重要基石。11月26日，经国务院同意，工业和信息化部、国家网信办、国家发展改革委联合印发《新一代通信网建设实施方案》，提出到2030年建成覆盖完善、性能领先的新一代通信网。', 'published', '中国经营网', FALSE, 100, 5, '2026-11-28T02:01:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-1348c89602d74fe9', '100001', 'news-category-markets', 'article-202611283942114427', '渝三峡A新增长曲线显现', '传统涂料企业重庆三峡油漆股份有限公司（以下简称“渝三峡A”）对重庆蔚蓝时代节能技术有限公司（以下简称“蔚蓝时代”）的产业并购，正在交出阶段性答卷。11月27日，渝三峡A相关负责人在接受《证券日报》记者采访时说，自纳入公司合并报表后，蔚蓝时代收入增长显著提速，多场景落地持续推进。与此同时，渝三峡A“涂料+新材料”双轮驱动的战略框架逐步落地，一条新的增长曲线已现雏形。', 'published', '证券日报', FALSE, 100, 3, '2026-11-28T01:22:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-c59451e3281d84f7', '100001', 'news-category-markets', 'article-202611283942114928', '固德威：调排产拓渠道加快去库存', '11月27日，固德威技术股份有限公司（以下简称“固德威”）举行2026年三季度业绩说明会，公司管理层围绕经营业绩、库存管理、储能业务发展及未来市场布局等话题与投资者展开交流。固德威主要从事太阳能、储能等新能源电力电源设备的研发、生产和销售，主营产品包括光伏并网逆变器、储能逆变器、储能电池及户用系统等，并面向家庭、工商业用户及地面电站提供智慧能源管理整体解决方案。', 'published', '证券日报', FALSE, 100, 3, '2026-11-28T01:22:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-0b5bc9a8c270f696', '100001', 'news-category-markets', 'article-202611283942114230', '理性开展募投项目纠偏', '■金婉霞近期，锦浪科技股份有限公司、辽宁成大生物股份有限公司、安徽元琛环保科技股份有限公司等多家A股上市公司相继披露拟终止或变更部分募集资金投资项目的公告，涉及新能源、生物医药、环保新材料等多个领域。在技术迭代加快、产业竞争格局不断变化的背景下，企业根据市场环境变化适时调整募投项目，无可厚非。但此类事件接连出现，给上市公司的投资决策与公司治理带来了诸多启示。', 'published', '证券日报', FALSE, 100, 2, '2026-11-28T01:21:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-3009ca8142084eb6', '100001', 'news-category-markets', 'article-202611283942114877', '八方股份：订单及生产逐渐恢复正常', '11月27日，八方电气（苏州）股份有限公司（以下简称“八方股份”）召开2026年三季度业绩说明会。公司董事长兼总经理王清华、独立董事张为公、董事会秘书周琴、财务总监吴蔚蔚就海外市场去库存与订单回暖、汇率应对、现金流与库存管理、行业竞争环境及新品类拓展等市场关切问题，对《证券日报》记者及线上投资者一一作出回应。', 'published', '证券日报', FALSE, 100, 3, '2026-11-28T01:21:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-4ab357784dbf7337', '100001', 'news-category-markets', 'article-202611283942116487', '与投资者互动答题前要审好题', '■桂小笋日前，证券交易所向某公司下发了一封监管函。公司在互动易平台上的回复没有一句假话，没有蹭热点，也没有任何暗示，却依然被认定违规。原因在于，投资者提问时问到的产品进展并不属实，而公司仅以套话带过，并未先澄清不属实情况，因此答复被认为不完整。一份“什么都没说错”的回复换来一纸监管函，这对所有上市公司都是一个提醒：与投资者互动，答题是基本功，审题才是真功夫。', 'published', '证券日报', FALSE, 100, 2, '2026-11-28T01:21:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-500c716da563f399', '100001', 'news-category-markets', 'article-202611283942114668', '中南文化拟控股江阴天力', '11月27日晚间，中南红文化集团股份有限公司（以下简称“中南文化”）发布公告称，公司拟取得江阴天力燃气有限公司（以下简称“江阴天力”）控股权。据初步测算，本次交易预计构成重大资产重组。公告显示，中南文化拟以支付现金的方式购买上海儒驭能源投资有限公司（以下简称“上海儒驭”）及上海慧冉投资有限公司（以下简称“上海慧冉”）各100%的股权。', 'published', '证券日报', FALSE, 100, 2, '2026-11-28T01:21:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-7c880e125a75774e', '100001', 'news-category-markets', 'article-202611283942114771', '注销式回购考验上市公司资本配置能力', '■张芗逸11月26日，武汉精测电子集团股份有限公司发布回购股份报告书，明确拟以1亿元至2亿元资金回购股份，用于注销并相应减少公司注册资本。今年以来，注销式回购持续扩容。证监会数据显示，今年前10个月，沪深两市645家上市公司共披露700单、合计2377亿元股份回购计划，其中回购注销金额1150亿元，占比近50%，回购计划金额、回购注销金额及占比均创历史新高。', 'published', '证券日报', FALSE, 100, 2, '2026-11-28T01:21:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-90d52bca91db7f35', '100001', 'news-category-markets', 'article-202611283942115822', '中国铁塔：数字基建贯通“一河三山”', '在位于宁夏固原市的六盘山上，一新一旧两座通信铁塔遥相呼应。“那座颜色已褪成深褐色的高大铁塔是六盘山上的第一座通信铁塔，建成于1998年前后；另一侧的白色铁塔是今年新建的。”中国铁塔股份有限公司（以下简称“中国铁塔”）固原市分公司副总经理王小强指着远处的通信铁塔向《证券日报》记者介绍。', 'published', '证券日报', FALSE, 100, 6, '2026-11-28T01:21:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-9de8620259d2b7e1', '100001', 'news-category-markets', 'article-202611283942114549', '明星电力详解综合能源服务商发展路径', '明星电力详解综合能源服务商发展路径', 'published', '证券日报', FALSE, 100, 3, '2026-11-28T01:21:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-a69c0f84c3f33afd', '100001', 'news-category-markets', 'article-202611283942114332', '上市公司合规管控应穿透延伸', '■吴奕萱近日，浙江亿田智能厨电股份有限公司（以下简称“亿田智能”）公告披露，公司控股股东、实控人的一致行动人嵊州市亿顺投资管理合伙企业（有限合伙）、嵊州市亿旺投资管理合伙企业（有限合伙）收到浙江证监局警示函。', 'published', '证券日报', FALSE, 100, 2, '2026-11-28T01:21:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-fa7ba3fe1b4742d5', '100001', 'news-category-markets', 'article-202611283942115079', '天津港：智慧零碳码头迈向新一程', '在天津港（集团）有限公司（以下简称“天津港集团”）旗下天津港第二集装箱码头有限公司（以下简称“二集司”）的码头上，一艘14万吨的货轮正缓缓驶来，准备进入泊位卸货。岸桥吊具起落，一辆辆人工智能运输机器人（ART）往返于船边和堆场，抓取、起吊、落下，现场操作人员寥寥无几。二集司工作人员告诉《证券日报》记者，这艘船次日就可以离开泊位。', 'published', '证券日报', FALSE, 100, 5, '2026-11-28T01:21:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-fef21b34abcbcea0', '100001', 'news-category-markets', 'article-202611283942115227', '模型推理等环节需求提升 月内10余家上市公司披露算力订单', '近期，微盟集团、北京并行科技股份有限公司（以下简称“并行科技”）、行云科技股份有限公司（以下简称“行云科技”）等多家上市公司相继披露算力采购、租赁及服务合同进展。随着AI（人工智能）应用加速商业化，算力需求正从大模型训练向模型推理等应用环节进一步延伸。这不仅为算力服务企业带来了新的市场需求，也吸引了部分AI应用企业及传统行业企业布局算力基础设施及相关服务业务。', 'published', '证券日报', FALSE, 100, 4, '2026-11-28T01:21:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-ff3fe23648e250dc', '100001', 'news-category-markets', 'article-202611283942116012', '多维织密担保风险管理全链条', '■李亚男万得数据显示，今年以来，已有19家A股公司（含5家已退市公司）因违规对外担保受到行政处罚、被采取监管措施或被给予纪律处分。担保是融资中常见的增信安排，关键要看签出去的信用有没有人管、能不能管得住。', 'published', '证券日报', FALSE, 100, 3, '2026-11-28T01:21:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-427f1d6292e46c36', '100001', 'news-category-markets', 'article-202611283942116387', '央企布局战略性新兴产业跑出加速度 去年以来整合资产规模达2.3万亿元', '11月27日，国务院国资委召开中央企业专业化整合推进会。这是继11月18日国务院国资委举办“进一步深化国资国企改革专题研讨班”后，对中央企业专业化整合工作的再次部署。《证券日报》记者从现场获悉，去年以来，各中央企业共开展整合项目1100余个，涉及资产规模约6.8万亿元。', 'published', '证券日报', FALSE, 100, 5, '2026-11-28T01:16:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-660fbbc61b308157', '100001', 'news-category-markets', 'article-202611283942115768', '多家银行披露优先股赎回进展', '银行优先股正加速退出市场。万得数据显示，今年以来，已有8家上市银行披露优先股赎回或拟赎回方案，合计公告赎回规模1855亿元，超过2025年全年境内银行优先股赎回总量。南开大学金融学院教授田利辉在接受《证券日报》记者采访时表示，资金成本差异是银行赎回优先股最直接动因。', 'published', '证券日报', FALSE, 100, 3, '2026-11-28T01:16:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-9f8eb2b7699f2f91', '100001', 'news-category-markets', 'article-202611283942115446', '华安证券：深耕产业 打造科技投行', '今年7月份，国产DRAM（动态随机存取存储器）龙头长鑫科技集团股份有限公司（以下简称“长鑫科技”）登陆科创板，成为资本市场瞩目的焦点。而在追问这家企业的成长故事时，市场也把目光投向了它身后的资本“陪跑者”——华安证券股份有限公司（以下简称“华安证券”）。', 'published', '证券日报', FALSE, 100, 6, '2026-11-28T01:16:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-e477b6f5c623b18f', '100001', 'news-category-markets', 'article-202611283942116291', '前10个月规模以上工业企业利润同比增长16.0% 全国工业生产总体平稳 新动能快速成长', '11月27日，国家统计局发布数据显示，今年前10个月，全国工业生产总体平稳，新动能快速成长，带动规模以上工业企业利润同比增长16.0%，较前9个月加快0.5个百分点，今年以来继续保持两位数增长。10月份，全国规模以上工业企业利润同比增长20.1%，较9月份加快5.7个百分点。', 'published', '证券日报', FALSE, 100, 4, '2026-11-28T01:16:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-ea778609dc03359b', '100001', 'news-category-markets', 'article-202611283942115525', '2026年全球系统重要性银行名单出炉 我国五大银行分组保持不变', '日前，金融稳定理事会（FSB）公布2026年全球系统重要性银行（G-SIB）名单，共计29家机构进入名单，数量与上年保持一致。其中，工商银行、农业银行、中国银行、建设银行、交通银行等5家中资银行进入名单，与2025年保持一致。', 'published', '证券日报', FALSE, 100, 3, '2026-11-28T01:16:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-f2099dae0f89a2e9', '100001', 'news-category-markets', 'article-202611283942114124', '中国证监会查处两起证券误导信息案件', '11月27日，据中国证监会官网消息，近日，中国证监会对安某、乔某涉嫌编造传播证券市场误导性信息依法作出行政处罚，严厉打击借网络平台“玩梗”制造流量、煽动股票跟风炒作的违法行为，维护资本市场信息传播与交易秩序。', 'published', '证券日报', FALSE, 100, 2, '2026-11-28T01:16:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-18ed00b8fb6f543d', '100001', 'news-category-markets', 'article-202611283942117411', '稳市机制守住底线 改革攻坚打开空间 资本市场稳健发展韧性强信心足', '开栏语：资本市场事关经济发展大局。11月27日召开的国务院常务会议对资本市场稳市、改革、监管等工作作出系统部署，明确逆周期调节与改革攻坚并举，持续完善稳市机制、壮大中长期资金力量、深化多层次资本市场改革、强化全链条监管。', 'published', '证券日报', FALSE, 100, 7, '2026-11-28T01:15:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-7cda490ea9243716', '100001', 'news-category-markets', 'article-202611283942117598', '三大积极因素共振 A股市场放量上涨', '11月27日，A股市场放量普涨。万得数据显示，截至当日收盘，上证指数、深证成指、创业板指和科创综指分别收报于3606.49点、10814.02点、2443.96点和1489.77点，分别上涨3.73%、7.24%、11.61%和14.21%。沪深北三市成交总额达2.02万亿元，较前一交易日增加6913亿元。', 'published', '证券日报', FALSE, 100, 2, '2026-11-28T01:15:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-91b6d922f504a1eb', '100001', 'news-category-markets', 'article-202611283942117037', '上市公司要紧抓城市更新商机', '■王丽新11月23日，北京市人民政府发布《北京市“十五五”时期城市更新规划》，明确城市更新成为北京进入减量发展阶段后城市建设的主要抓手。11月24日，住房城乡建设部办公厅公布《实施城市更新行动可复制经验做法清单（第五批）》。接连两日，两项城市更新重点工作内容相继公布。将其放在一起看，信号清晰：城市更新不仅是民生投入，更是推动经济发展的重要手段。', 'published', '证券日报', FALSE, 100, 4, '2026-11-28T01:15:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-a3b17efde2dd0c51', '100001', 'news-category-markets', 'article-202611283942117237', '“2026证券市场年会”在京举行 聚力“十五五”开局 绘就资本市场新图景', '11月27日，由《证券日报》社有限责任公司主办的“2026证券市场年会”在北京举行。本次年会以“韧性与活力——共筑资本市场新生态”为主题，汇聚行业协会负责人、专家学者、上市公司及金融机构代表等各界嘉宾，围绕资本市场改革新形势、市场新变化与产业新需求，共话资本市场深化改革路径、投融资发展新模式，研判高水平对外开放带来的机遇与挑战。', 'published', '证券日报', FALSE, 100, 5, '2026-11-28T01:15:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-094ef3716e525767', '100001', 'news-category-markets', 'article-202611283942113957', '智利国家铜业公司称：今年前9个月自有铜产量为853,000吨 前9个月税前亏损14亿美元', '智利国家铜业公司称，今年前9个月自有铜产量为853,000吨，前9个月税前亏损14亿美元。', 'published', '财联社', FALSE, 100, 1, '2026-11-28T01:09:21Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-12f867ae74de63a4', '100001', 'news-category-markets', 'article-202611283942108291', '2026粤港澳大湾区服务贸易大会暨“AI+服务贸易”专题对接活动在穗举行 51个服务贸易项目现场签约', '11月26日上午，广东省商务厅、香港特别行政区政府商务及经济发展局、澳门特别行政区招商投资促进局联合主办的2026粤港澳大湾区服务贸易大会暨“AI+服务贸易”专题对接活动在中国进出口商品交易会展馆举行，相关政府部门、行业专家、服务贸易企业、人工智能服务供应商、商协会、驻穗领馆及境外商协会、参展商采购商和媒体代表超过600人参加。', 'published', '信息时报', FALSE, 100, 2, '2026-11-28T00:18:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-f442dfaca998b4cc', '100001', 'news-category-markets', 'article-202611283942108639', '黄沙水产市场旧址将整体拆除新建 投资约7.3亿元，打造“最广州”文化生活体验中心', '信息时报讯（记者郭展鹏）黄沙水产市场搬迁后，旧址将迎来升级改造。近日，“黄沙水产市场旧址升级改造项目勘察设计”招标公告发布，项目投资总额约7.3亿元。项目作为沙面打造国际消费和文化交流双中心的配套功能，需结合沙面“双中心”的整体规划统筹设计，拟整体拆除新建，拆除建筑51680平方米。', 'published', '信息时报', FALSE, 100, 4, '2026-11-28T00:18:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-00abc3987c0c4789', '100001', 'news-category-markets', 'article-202611283942108327', '广州国际汽车展览会开幕 1106台展车亮相，5000万元购车专项补贴现场发放', '羊城秋日，珠江之畔暖阳正好。11月27日，位于琶洲的中国进出口商品交易会展馆外人流如织，第二十四届广州国际汽车展览会拉开帷幕。本届车展以“新科技·新生活”为主题，展区包括广交会展馆A、D两区室内展厅、南北广场室外展区和广交会堂，总面积22万平方米；展车1106台，其中首发新车115台、新能源车707台。展会同期还将举办多场峰会、论坛和沙龙，围绕产业新趋势展开研讨。', 'published', '信息时报', FALSE, 100, 4, '2026-11-28T00:18:40Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-a37e504f0a300a60', '100001', 'news-category-markets', 'article-202611273942106287', '城市24小时 | “强省会”突围战，北方大省再开一局', '河北日报消息，11月26日，河北省第十一次党代会开幕。当天，河北省委主要领导在参加石家庄市和辛集市代表团讨论时再度强调，大力实施强省会战略，打造带动全省高质量发展的强力增长极。具体而言，要紧扣“一地三区”发展战略，提升经济首位度、增强辐射带动力。要在全国现代商贸物流重要基地建设中做强主枢纽，加快建设国家物流枢纽承载城市，提升正定国际机场区域航空枢纽功能，做实做强石家庄国际陆港。', 'published', '每日经济新闻', FALSE, 100, 9, '2026-11-27T23:58:30Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-a98dc479fb0fb32f', '100001', 'news-category-markets', 'article-202611273942104731', '灵活就业人群平均退休准备指数低于一般居民，业内建议应推动“三支柱”协调发展', '近年来，政策层面对灵活就业人员的关注持续加码。2025年，中办、国办印发《关于进一步保障和改善民生着力解决群众急难愁盼的意见》，明确提出“健全灵活就业人员、农民工、新就业形态人员社会保险制度，全面取消在就业地参加社会保险的户籍限制”；“十五五”规划建议进一步将“提高灵活就业人员、农民工、新就业形态人员参保率”纳入健全社会保障体系的部署之中。', 'published', '每日经济新闻', FALSE, 100, 5, '2026-11-27T23:54:31Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-20b6e2e9e4cbab7f', '100001', 'news-category-markets', 'article-202611273942103330', 'Codelco审视智利百年丘基卡马塔露天矿的未来', '【Codelco审视智利百年丘基卡马塔露天矿的未来】智利国家铜业公司（Codelco）表示，在工会对丘基卡马塔（Chuquicamata）百年铜矿部分设施可能被关闭表达担忧后，该公司正在重新评估该矿区部分业务的未来。这家智利国有矿业公司在一份声明中表示，目前尚未做出影响整个分部的即时决定，但承认作为对丘基卡马塔商业模式审查的一部分，公司正在评估“某些区域和流程的运营连续性”。Codelco称，正在研究确保该矿山长期可行性的替代方案，并正与工会讨论相关提案。', 'published', '财联社', FALSE, 100, 1, '2026-11-27T23:49:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-fa300ab5c5671a30', '100001', 'news-category-markets', 'article-202611273942102230', '五年电动化变革后，广州车展迎来新课题 | 2026广州车展', '11月27日早8时许，距离广汽国际发布会开始还有几十分钟，工作人员正忙着接待海外媒体和经销商。广汽国际的中方员工用英语、西班牙语和阿拉伯语，与来自南美、东南亚和中东的来客沟通。“我现在正在广州车展的现场，稍后会给大家带来各家企业最新的汽车技术和产品。”一位智利媒体从业者面对镜头，向海外观众直播车展。他的同行站在一旁，高声讨论中国汽车的新变化。', 'published', '界面新闻', FALSE, 100, 6, '2026-11-27T23:45:46Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-57c975af35b7da34', '100001', 'news-category-markets', 'article-202611273942096386', '都发中心：传承千年治水智慧 服务新时代江河战略', '11月26日，以“治水安邦·文化兴邦——从治水之道到治国之道的江河战略”为主题的“都江堰·江河战略论坛”在成都都江堰市举办。四川省都江堰水利发展中心（以下简称“都发中心”）党委副书记李彦富参与见证《江河治理·都江堰倡议》发布，党委委员、副主任吴鉴参与分论坛“幸福江河”专场主题对话。作为论坛配套活动，“兴水惠民——中国江河治理成就展”于25日正式开展。', 'published', '新华财经', FALSE, 100, 4, '2026-11-27T23:42:01Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-291a3df2b37bd555', '100001', 'news-category-markets', 'article-202611273942093354', '锚定江河战略 四川水发集团展现蜀地治水新实践', '11月26日，“都江堰·江河战略论坛”在成都都江堰市举行，新时代江河治理的前沿思考在此交汇碰撞。作为四川现代水网建设的核心攻坚力量，四川省水利发展集团有限公司（以下简称“四川水发集团”）成为本次论坛的一抹亮色。', 'published', '新华财经', FALSE, 100, 5, '2026-11-27T23:33:51Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-3f8171e87b9aa2a6', '100001', 'news-category-markets', 'article-202611273942095526', '上汽MG：明年1月1日起在中国大陆停产燃油车', '新京报贝壳财经讯（记者白昊天)11月27日，上汽MG发文宣布：为顺应全球化新能源发展趋势，根据公司发展战略需求，上汽MG品牌决定自2027年1月1日起，面向中国大陆市场停产在售版本纯燃油车型。上汽MG品牌决定自2027年1月1日起，面向中国大陆市场停产在售版本纯燃油车型。', 'published', '新京报', FALSE, 100, 1, '2026-11-27T23:32:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-8b9436dce5695531', '100001', 'news-category-markets', 'article-202611273942091627', '纷美利乐回应最高法宣判：服从判决', '11月27日，针对当天最高法公开宣判利乐垄断后继民事诉讼两案，纷美相关人士向北京商报记者回应称，“纷美包装尊重并拥护最高法终审判决，纷美将继续深耕无菌包装主业，以品质打造民族品牌。”利乐公司官网发布声明称，“已收到最高人民法院对我司所提起的上诉案件作出的终审判决。尽管对判决结果感到遗憾，利乐公司服从最高人民法院的判决，对该案件不再寻求进一步法律救济”。', 'published', '北京商报', FALSE, 100, 1, '2026-11-27T23:31:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-8c6fbafdd559ffee', '100001', 'news-category-markets', 'article-202611273942092382', '近岸蛋白业绩继续增收不增利 赋能AI相关业务收入占比不足2% |直击业绩会', '《科创板日报》11月27日讯（记者史士云）“公司前三季度研发投入合计5569.85万元，同比增长38.39%，占营业收入比例为44.65%。研发投入全部费用化，增长主要系研发人员薪酬、研发领料、研发设备折旧等增加所致。', 'published', '财联社', FALSE, 100, 5, '2026-11-27T23:30:02Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-32bf44d8abf856c7', '100001', 'news-category-markets', 'article-202611273942091264', '出资千万元跨界投资！民丰特纸参投1.17亿元私募，投向芯片半导体与商业航天等', '11月27日盘后，民丰特纸（600235.SH，股价4.98元，市值17亿元）披露《与私募基金合作投资公告》，公司拟作为有限合伙人，以自有资金认缴出资1000万元参与设立青岛景启股权投资合伙企业（有限合伙）（以下简称青岛景启），占基金初始认缴出资总额的8.56%。该合伙企业初始募集规模为11680万元，由北京新鼎荣盛资本管理有限公司担任普通合伙人及基金管理人。', 'published', '每日经济新闻', FALSE, 100, 4, '2026-11-27T23:30:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-1241fcd36e07dc0d', '100001', 'news-category-markets', 'article-202611273942089648', '稳市“不隔夜”！十大券商 重磅发声', '【导读】国常会释放“稳市场”鲜明信号，十大券商首席最新观点来了国常会重磅定调，券商首席点评来了！11月27日，国务院总理李强主持召开国务院常务会议，研究持续深化资本市场投融资综合改革工作。随着午间利好消息的释放，A股市场立即暴涨，上证指数强势收复3600点；科技成长风格领涨市场，科创综指、创业板指分别暴涨14.21%、11.61%。', 'published', '中国基金报', FALSE, 100, 10, '2026-11-27T23:26:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-d61265cc88edded7', '100001', 'news-category-markets', 'article-202611273942088932', '11.99万元起 智能零压SUV东风日产NX7正式上市', '11月27日，东风日产NX7在2026广州车展上正式上市，并同步开启全国交付。新车共推出三个级别，上市限时权益价11.99万—13.99万元。其中，320Pro版上市限时权益价11.99万元，入门即配宁德时代40.9度大电池；320Max版上市限时权益价12.99万元，满配沙发厂舒适；320Ultra激光雷达版上市限时权益价13.99万元，智能化实力第一梯队。', 'published', '北京商报', FALSE, 100, 7, '2026-11-27T23:26:21Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-aff1ac28cb2e9fbe', '100001', 'news-category-markets', 'article-202611273942089161', '光大银行：过去12个月及拟与光大集团及其下属企业发生关联交易约132.97亿元', '上证报中国证券网讯（记者常佩琦）11月27日，光大银行发布的关联交易公告显示，光大银行为光大证券核定人民币115亿元综合授信额度，期限12个月，信用方式。为光大控股核定非承诺性循环贷款2.5亿美元（约合17.97亿元人民币），期限360天，信用方式。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:25:29Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-ef030d17cb43ce8d', '100001', 'news-category-markets', 'article-202611273942089571', '光大银行：为招商证券核定人民币150亿元综合授信额度', '上证报中国证券网讯（记者常佩琦）11月27日，光大银行发布的关联交易公告显示，光大银行为招商证券核定人民币150亿元综合授信额度，期限12个月，信用方式，将超过该行最近一期经审计净资产绝对值的0.5%。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:25:18Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-4f2afa1a1c909ede', '100001', 'news-category-markets', 'article-202611273942087990', '山姆羽绒服爆红，“隐形”纺织大省想出圈久矣', '一件卖爆单的羽绒服，让向来低调的北方纺织大省意外来到聚光灯下。近段时间，一款标价399元、充绒量300克的羽绒服在全国多地山姆门店卖断货，各地网友“求代购”心切刷屏网络。就在这件被称为“性价比之王”的羽绒服吊牌上，一行本不显眼的“产地：山东泰安”字样，却引发公众热议。有分析直指：充绒量300克，80%白鸭绒，光绒的成本就占到售价三成以上。', 'published', '每日经济新闻', FALSE, 100, 9, '2026-11-27T23:25:04Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-e0e32211f46c5183', '100001', 'news-category-markets', 'article-202611273942087783', '金价大幅回调引银行密集预警，黄金资产如何配置？世界黄金协会给出5%至28%动态配置建议', '11月以来，国际金价剧烈震荡，出现大幅回调。面对市场波动，11月25日，中国银行发布关于加强贵金属市场风险防范的提示。此前，上海黄金交易所及工商银行、建设银行、招商银行等多家银行同样发布贵金属投资风险提示，提醒投资者审慎评估风险、合理控制仓位，避免盲目跟风操作。', 'published', '每日经济新闻', FALSE, 100, 5, '2026-11-27T23:25:03Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-7be1396b3559d58a', '100001', 'news-category-markets', 'article-202611273942089476', '引望、启境与神州租车三方战略签约 融合华为乾崑智驾能力', '上证报中国证券网讯（记者俞立严）11月27日，引望、启境汽车与神州租车在广州共同签署三方战略合作协议。根据协议，三方将围绕华为乾崑APP生态开展合作探讨，覆盖租车服务体验、联合运营、积分场景等方向，并把数字钥匙、ETC便捷通行、华为乾崑智驾等能力放进一次完整行程里，共同探索“租车即体验、体验促信任”的生态创新模式。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:24:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-f23ecbe13dfb803f', '100001', 'news-category-markets', 'article-202611273942089895', '农业银行助力法国农业信贷银行发行熊猫债', '上证报中国证券网讯（记者范子萌）11月26日，农业银行担任牵头主承销商，助力法国农业信贷银行在中国银行间债券市场完成2026年度第二单熊猫债发行。本期债券创新采用三品种同步发行模式：3年期品种发行规模30亿元，票面利率1.75%；5年期品种发行规模30亿元，票面利率1.85%；10年期品种发行规模10亿元，票面利率2.35%。法国农业信贷银行是欧洲大型银行集团。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:24:48Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-987f4f1126ddaaf3', '100001', 'news-category-markets', 'article-202611273942090156', '瑞丰银行：近期国内外贵金属价格波动加剧 建议投资者做好投资风险管控', '上证报中国证券网讯（彭飞记者操子怡）11月27日，瑞丰银行在官微发布《关于加强贵金属市场风险防范的提示》。该行称，近期国内外贵金属价格波动加剧，投资交易风险加大，建议投资者提高风险防范意识，做好投资风险管控，理性安排投资交易，合理控制贵金属持仓规模，防范贵金属价格波动风险。11月27日，国际金价大幅反弹。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:24:28Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-01e52440192dad53', '100001', 'news-category-markets', 'article-202611273942086869', 'ST中珠全资子公司拟出售资产 货值超3.32亿元', '上证报中国证券网讯（记者荆淮侨）11月27日晚间，ST中珠发布公告称，根据业务发展需要，全资子公司中珠红旗拟采取在市场寻找意向交易方、公开挂牌等方式出售持有的商铺及其他商业存量资产。公司称，本次交易系基于公司整体发展战略及资产结构优化需要，有利于优化公司资源配置、盘活存量资产，促进公司聚焦核心业务，推动公司实现高质量发展。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:23:59Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-dae623381b62a214', '100001', 'news-category-markets', 'article-202611273942086566', '广汽传祺发布星源超级双擎混动技术', '上证报中国证券网讯（记者李五强）11月27日，第二十四届广州车展上，广汽传祺正式对外亮相星源超级双擎（HEV+）混动技术，尝试解决传统油混智能化不足的行业痛点。星源超级双擎采用“多场景电驱优先”设计思路，搭载行业首创5.4kWh高倍率安全电池。', 'published', '上海证券报·中国证券网', FALSE, 100, 2, '2026-11-27T23:23:25Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-a7a551243f51dddb', '100001', 'news-category-markets', 'article-202611273942085970', '弘盛资本盛海峰：投资应深耕产业生态 独立研判技术逻辑与商业价值', '上证报中国证券网讯（记者王墨璞嘉）在近日举办的SIA2026科学护肤创新联盟年度大会上，弘盛资本创始管理合伙人盛海峰表示，投资不应止步于财务层面，只有深入产业生态，独立研判技术逻辑与商业价值，才能看清项目本质。他通过联合发起皮肤健康联盟SIA科盟等方式，立足产业底层逻辑，共建产业科创生态，夯实投资决策基础。目前，SIA科盟联盟企业已超百家。', 'published', '上海证券报·中国证券网', FALSE, 100, 2, '2026-11-27T23:23:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-d83cdf082a060c6e', '100001', 'news-category-markets', 'article-202611273942087417', '德邦证券研究所所长、首席经济学家程强：稳市行为的市场预期更为稳定', '上证报中国证券网讯（记者闫刘梦）11月27日召开的国务院常务会议对资本市场工作作出部署。德邦证券研究所所长、首席经济学家程强在接受上证报记者采访时表示，从会议对资本市场投融资综合改革的整体表述来看，这反映出顶层定调升级，会议明确“资本市场事关经济发展大局”“坚持目标导向、问题导向，坚持逆周期调节和改革攻坚两手抓”。程强认为这反映了政策重心从单一融资功能转向投融资两端协同。', 'published', '上海证券报·中国证券网', FALSE, 100, 3, '2026-11-27T23:22:54Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-e789e6b05eccf92a', '100001', 'news-category-markets', 'article-202611273942086778', '光大银行：为中信金融资产核定人民币300亿元综合授信额度', '上证报中国证券网讯（记者常佩琦）11月27日，光大银行发布的关联交易公告显示，光大银行为中信金融资产核定人民币300亿元综合授信额度，期限1年，信用方式，将超过该行最近一期经审计净资产绝对值的0.5%。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:22:17Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-bde565be11688828', '100001', 'news-category-markets', 'article-202611273942087516', 'DeepSeek开始“算细账”：AI大模型免费换流量的时代正在收尾', '《科创板日报》11月27日讯（记者黄心怡）AI大模型应用模式正在发生变化。《科创板日报》记者发现，DeepSeek安卓端App更新至2.10.0版本后，新增了一个功能按钮，用户可查看每轮对话消耗额度对应的具体资费。目前，其计费模式与API官方文档中的计费模式相同。此举或为后续推出App付费模式做铺垫。', 'published', '财联社', FALSE, 100, 4, '2026-11-27T23:22:16Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-530f7c98ea8bada2', '100001', 'news-category-markets', 'article-202611273942086431', '光大银行：2027-2029年与光大集团系关联方服务类关联交易合计限额96.4亿元', '光大银行：2027-2029年与光大集团系关联方服务类关联交易合计限额96.4亿元', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:22:10Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-53924ff548d16357', '100001', 'news-category-markets', 'article-202611273942085266', '北交所公布2025—2026年度信披评价结果 与再融资、并购重组审核相衔接', '上证报中国证券网讯（记者张雪）北京证券交易所11月27日发布2025—2026年度上市公司信息披露工作评价结果。整体来看，30家公司连续两年评级为A，36家公司评级提升，评价工作的激励约束作用得到有效发挥。具体来看，该评价的评价期间为2025年7月1日至2026年6月30日，评价对象为2025年12月31日前上市的286家公司。', 'published', '上海证券报·中国证券网', FALSE, 100, 3, '2026-11-27T23:21:57Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-20234e91c715231a', '100001', 'news-category-markets', 'article-202611273942084133', '光大银行：为中远海发核定人民币32亿元单一客户总量限额', '上证报中国证券网讯（记者常佩琦）11月27日，光大银行发布的关联交易公告显示，光大银行为中远海发核定人民币32亿元单一客户总量限额，期限3年。其中，综合授信额度20亿元人民币，期限3年，信用方式；一般风险债券投资额度12亿元人民币，期限2年，信用方式。上述交易将超过该行最近一期经审计净资产绝对值的0.5%。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:21:43Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-73d48f999111e081', '100001', 'news-category-markets', 'article-202611273942084843', '厦门象屿2.83亿元中期分红即将落地 管理层对全年经营抱有信心', '上证报中国证券网讯（彭飞记者操子怡）11月27日，厦门象屿管理层在三季度业绩说明会上说，公司董事会已审议通过2026年中期利润分配方案，拟每股派发现金红利0.1元（含税），此次中期分红将于2026年11月30日完成。此外，厦门象屿管理层介绍，公司在资源端持续强化上游稳定供应能力，在工贸一体端新签多艘船舶订单，将继续夯实前三季度稳健经营理念，对全年以及未来的经营充满信心。', 'published', '上海证券报·中国证券网', FALSE, 100, 4, '2026-11-27T23:21:34Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-fc8795b3979f189e', '100001', 'news-category-markets', 'article-202611273942084988', '第一创业证券副总裁杨维彬：立足固定收益特色 推进买方投顾转型', '上证报中国证券网讯（记者唐燕飞）近日，第一创业证券获评上海证券报2026年“上证智鹰·金理财”新锐财富管理机构。对此，第一创业证券副总裁杨维彬接受上海证券报记者采访表示，第一创业证券的差异化优势在于资管端的“固收+、FOF、多策略”能力，公司财富管理业务努力在低波动前提下，拓宽多元收益来源。', 'published', '上海证券报·中国证券网', FALSE, 100, 2, '2026-11-27T23:21:19Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-4b69ff4239e68a7a', '100001', 'news-category-markets', 'article-202611273942084347', '富创精密：拟1亿至2亿元回购股份用于员工持股或股权激励', '上证智讯11月27日晚间，富创精密发布公告称，公司拟以集中竞价交易方式回购公司股份，回购资金总额不低于1.00亿元且不超过2.00亿元，回购价格上限为182.53元/股，资金来源为公司自有资金和/或自筹资金（含回购专项贷款资金），回购股份全部用于员工持股计划及/或股权激励。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:21:02Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-be7b058b257d57e1', '100001', 'news-category-markets', 'article-202611273942084447', '大华股份：拟0元受让华视智检35%股权 持股升至88.2%', '上证智讯11月27日晚间，大华股份发布公告称，公司第九届董事会第五次会议审议通过《关于收购浙江华视智检科技有限公司少数股权暨关联交易的议案》，公司拟以0元对价受让控股子公司浙江华视智检科技有限公司（以下简称“华视智检”）少数股东陈爱玲女士所持有的华视智检35%股权，对应注册资本1750万元，已实缴1750万元。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:21:02Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-119c9da81fd88ad9', '100001', 'news-category-markets', 'article-202611273942089924', '史诗级利好！14只科创ETF触及20cm涨停', '【导读】史诗级利好！14只科创ETF触及20cm涨停各位ETF投资者，“牛回，速归”！11月27日中午，国常会表态，要推动上市公司加大分红回购力度，加力发挥“国家队”稳市作用，进一步优化中央汇金公司的类“平准基金”功能，提供充足流动性保障。这也是国常会首次在1个月内两提资本市场。受政策利好刺激，A股市场午盘迎来大逆转，各大指数直线拉升。', 'published', '中国基金报', FALSE, 100, 4, '2026-11-27T23:21:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-ebeda87498cb6fac', '100001', 'news-category-markets', 'article-202611273942085692', '生态环境部：应对超强厄尔尼诺 重点从三方面加强大气执法监管', '上证报中国证券网讯（记者李苑）生态环境部生态环境执法局局长赵世新11月27日在例行新闻发布会上表示，超强厄尔尼诺往往会导致东亚冬季风偏弱，我国北方地区冷空气活动减少，大气扩展条件变差，容易出现长时间、大范围重污染过程，进一步加大了应对工作的难度。生态环境部将把有限的执法力量用在关键处，以最小的扰动、最低的代价，获得尽可能好的效果。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:20:54Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-5be0f840ad6d557a', '100001', 'news-category-markets', 'article-202611273942084668', '信测标准：全资子公司华中信测吸收合并武汉信测', '上证智讯11月27日晚间，信测标准发布公告称，公司于2026年11月27日召开第五届董事会第二十一次会议，审议通过《关于全资子公司之间吸收合并的议案》，同意由全资子公司华中信测标准技术服务（湖北）有限公司（以下简称“华中信测”）通过整体吸收合并的方式合并武汉信测标准技术服务有限公司（以下简称“武汉信测”）。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:20:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-605bf2812f5d7112', '100001', 'news-category-markets', 'article-202611273942084535', '粤海饲料：拟1亿至2亿元回购股份用于员工持股或股权激励', '上证智讯11月27日晚间，粤海饲料发布公告称，公司拟以集中竞价交易方式回购公司股份，回购资金总额不低于1.00亿元且不超过2.00亿元，回购价格不超过9.90元/股，资金来源为公司自有资金及自筹资金，回购股份用于股权激励或员工持股计划。该方案已经公司11月27日召开的第四届董事会第二十一次会议审议通过，属董事会审批权限范围，无需提交股东会审议。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:20:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-97e80c067131b384', '100001', 'news-category-markets', 'article-202611273942084768', '*ST卓然：股票被上交所终止上市 将于12月4日摘牌', '*ST卓然：股票被上交所终止上市 将于12月4日摘牌', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:20:39Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-f52293c96d8b6890', '100001', 'news-category-markets', 'article-202611273942084247', '11月27日晚间重要公告集锦', '11月27日晚间重要公告集锦', 'published', '上海证券报·中国证券网', FALSE, 100, 10, '2026-11-27T23:20:38Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-da96a52aea822e38', '100001', 'news-category-markets', 'article-202611273942083817', '国仪公司：获得W客户3132.36万元高端双束电子显微镜订单', '上证智讯11月27日晚间，国仪公司发布公告称，公司根据与W客户签订的《集团化框架采购协议》，于近日收到并接受W客户下达的多份采购订单，约定向W客户销售高端双束电子显微镜，上述订单总金额为3132.36万元（含税）。公告显示，上述合同属于公司日常经营性销售合同，公司已履行签署合同的内部审批程序，无需提交公司董事会、股东会审议，本次交易不构成关联交易，亦不构成重大资产重组。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:20:32Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-1bab9d6bba6a80d3', '100001', 'news-category-markets', 'article-202611273942085592', '生态环境部：移动源污染减排阶段性成效明显', '上证报中国证券网讯（记者李苑）生态环境部生态环境执法局局长赵世新11月27日在例行新闻发布会上表示，总体看，移动源合规达标和污染减排阶段性成效明显，实现“三个下降”：弄虚作假车检机构、违法超标重型车比例分别较2024年下降48和54个百分点；卫星遥感数据显示，在全国公路货运量同比上涨2.5%的情况下，高速公路区域氮氧化物柱浓度下降5.1%。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:20:27Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-942a0a5728c732bb', '100001', 'news-category-markets', 'article-202611273942083717', '粤海饲料：拟斥资1亿至2亿元回购股份', '上证报中国证券网讯（记者骆民）粤海饲料公告，公司拟以集中竞价交易方式回购公司股份，用于后续实施股权激励或员工持股计划。本次回购股份资金不低于1亿元且不超过2亿元，回购价格不超过9.9元/股。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:20:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-c6f7c85f75610c1a', '100001', 'news-category-markets', 'article-202611273942083917', '*ST数源：公司及6名责任人遭深交所公开谴责', '上证智讯11月27日晚间，深圳证券交易所发布《关于对数源科技股份有限公司及相关当事人给予公开认定等纪律处分的决定》称，根据中国证监会浙江监管局《行政处罚决定书》查明的事实，*ST数源2020年年报、2021年年报、2022年半年报存在虚假记载，涉及虚假视音频业务、虚假贸易业务及贸易业务错误使用总额法、虚假项目咨询服务三项。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:20:09Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-6fb37681ec62df2d', '100001', 'news-category-markets', 'article-202611273942081980', '江瀚新材董事长提议公司最高3亿元回购股份', '上证报中国证券网讯（记者丁鹏）11月27日晚，江瀚新材公告称，公司实际控制人、董事长甘书官当天提议公司以1.5亿元至3亿元回购股份，用于维护公司价值及股东权益，公司董事会已审议通过该回购方案。公告显示，甘书官基于对公司未来持续发展的信心和对公司价值的认可，综合考虑公司股价、经营情况及财务状况等因素，提出上述回购建议。', 'published', '上海证券报·中国证券网', FALSE, 100, 2, '2026-11-27T23:19:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-7b5af10b44c5db9e', '100001', 'news-category-markets', 'article-202611273942081880', '松发股份拟170亿投建海工装备制造项目 手握订单排至2030年｜速读公告', '财联社11月27日讯（记者陆婷婷）手握排至2030年的订单，松发股份(603268.SH)选择在行业景气周期继续加注。松发股份今日晚间公告称，其下属公司恒力造船(大连)有限公司拟投资约170亿元建设恒力重工绿色高端海工科技装备制造项目。这笔大额资本开支，是公司完成从传统陶瓷向船舶制造转型之后，新一轮面向高端海工赛道的产能加码。', 'published', '财联社', FALSE, 100, 3, '2026-11-27T23:19:33Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-3d772547c78fb442', '100001', 'news-category-markets', 'article-202611273942080692', '科尔尼发布《2026年全球城市指数报告》：上海升至第七位', '上证报中国证券网讯（记者宋薇萍）科尔尼近日发布《2026年全球城市指数报告》。报告显示，纽约、伦敦、巴黎、东京和新加坡仍稳居全球城市综合排名（GCI）前五，领先地位进一步巩固。排名前20%的城市平均得分增幅接近全部样本城市整体增幅的12倍。中国城市表现亮眼。北京位列第6，上海上升1位至第7，创近六年来最佳表现。长沙上升9位，青岛、济南各上升5位，广州、深圳各上升3位。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:18:06Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-d31615ff0e6aec48', '100001', 'news-category-markets', 'article-202611273942080328', '建发股份与越南GMD集团签署合作意向书 港口物流合作向业务实践延伸', '上证报中国证券网讯（彭飞记者操子怡）11月27日，建发股份官微发布消息称，11月26日，公司与越南GemadeptCorporation集团（下称“GMD集团”）签署合作意向书。据介绍，GMD集团是越南大型港口物流运营商，此次合作意向书的签署，标志着双方合作从战略层面进一步向业务实践延伸。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:18:00Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-d0b006b746d2971f', '100001', 'news-category-markets', 'article-202611273942080918', '低俗赌约引爆流量 监管零容忍净化市场信息生态', '上证报中国证券网讯（记者梁银妍）中国证监会11月27日通报，近日对安某、乔某涉嫌编造传播证券市场误导性信息依法作出行政处罚。经查，安某、乔某在网络平台分别发布涉及上市公司中公教育、共进股份的误导性信息，相关低俗言论经网络渠道大范围传播，导致两家上市公司股价异常波动。证监会决定对安某、乔某没收违法所得并处罚款。', 'published', '上海证券报·中国证券网', FALSE, 100, 4, '2026-11-27T23:17:26Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-3903b40b2ac69ed3', '100001', 'news-category-markets', 'article-202611273942079193', '银禧科技撤回对六名股东的起诉', '上证报中国证券网讯（记者李五强）银禧科技11月27日晚披露，公司已就此前提起的重大诉讼向东莞市第一人民法院提交撤诉申请，并收到法院送达的《民事裁定书》，法院受理了公司的撤诉申请，准许公司撤回起诉。这意味着此前将公司股东推上被告席的司法程序正式终结，也为持续数月的董事会换届争议画上阶段性句号。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:17:06Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-f5e65bbae213d409', '100001', 'news-category-markets', 'article-202611273942077969', '中铝国际签订65.56亿元海外EPC总承包合同', '11月27日晚间，中铝国际(601068)发布公告，公司与中铝几内亚正式签订《中国铝业几内亚氧化铝项目EPC总承包合同》。公司负责年产120万吨氧化铝生产线及其配套设施的设计、采购、施工。合同总金额预计约为人民币655,557万元。中铝几内亚为一家在几内亚共和国注册成立的股份有限公司，注册资本18000万几内亚法郎，主要经营Boffa铝土矿项目矿业活动。', 'published', '证券时报网', FALSE, 100, 2, '2026-11-27T23:16:58Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z'),
  ('news-item-01ec273857ee7825', '100001', 'news-category-markets', 'article-202611273942080428', '明阳智能：董事长提议公司1亿至1.5亿元回购股份', '上证智讯11月27日晚间，明阳智能发布公告称，公司董事会于2026年11月27日收到实际控制人、董事长兼首席执行官张传卫出具的《关于提议明阳智慧能源集团股份公司回购公司股份的函》。', 'published', '上海证券报·中国证券网', FALSE, 100, 1, '2026-11-27T23:16:42Z', '2026-11-28T00:00:00Z', '2026-11-28T00:00:00Z')
